SET NOCOUNT ON;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
PRINT 'Cód. cliente|Fecha|Documento|Cód. artículo|Cantidad';
SELECT REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(c.CODCLI)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), CONVERT(varchar(10),c.FECHA,23), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(CONCAT(NULLIF(LTRIM(RTRIM(c.SERIE)),'')+'-',CAST(CAST(c.NUMDOC AS bigint) AS varchar(20))))),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), REPLACE(REPLACE(REPLACE(REPLACE(ISNULL(LTRIM(RTRIM(l.CODART)),''),CHAR(9),' '),CHAR(13),' '),CHAR(10),' '),CHAR(124),' '), CAST(l.UNIDADES AS varchar(30))
FROM LINEFACT l JOIN CABEFACV c ON c.IDFACV=l.IDFACV
WHERE c.FECHA>=DATEADD(MONTH,-12,(SELECT MAX(FECHA) FROM CABEFACV)) AND l.UNIDADES>0 AND ISNULL(LTRIM(RTRIM(l.CODART)),'')<>''
ORDER BY c.CODCLI, c.FECHA, c.IDFACV, l.IDLIN;
